// Translation dictionary for DispatchOS.
//
// Four languages: en (default, US market), ru (team working language),
// es (Spanish scaffolding), fr (French scaffolding).
// ES and FR are starter scaffolds — keys fall back to EN at runtime.
//
// Convention:
//  - Keys are namespaced by surface (`nav.*`, `landing.*`, `login.*`).
//  - Values that need interpolation use `{name}` placeholders, resolved by
//    the `t()` helper at call-site.
//  - Missing keys fall back to EN then to the key itself at runtime and
//    surface a console.warn in dev so we catch drift.

export type Lang = "ru" | "en" | "es" | "fr";

export const LANGS: { code: Lang; label: string; flag: string; short: string }[] = [
  { code: "en", label: "English",  flag: "🇺🇸", short: "EN" },
  { code: "ru", label: "Русский",  flag: "🇷🇺", short: "RU" },
  { code: "es", label: "Español",  flag: "🇪🇸", short: "ES" },
  { code: "fr", label: "Français", flag: "🇫🇷", short: "FR" },
];

